import java.awt.*;import java.applet.Applet;public class RobotSearchDriver extends Applet{	private Obstacle an_obstacle = new Obstacle(50, 150, 100, 200);	private Goal your_goal = new Goal(256, 50);	private Room my_room = new Room();	Color[] colors = new Color[2];	Robot[] robots = new Robot[2];		private Graphics page;	public void init(){			robots[0] = new DiagonalRobot(this, an_obstacle, your_goal, 1, 1);		robots[1] = new RandomRobot(this, an_obstacle, your_goal, 1, 1);		colors[0] = new Color(0,255,255);		colors[1] = new Color(255,0,255);		setVisible(true);		page = getGraphics();		}	public void start(){			boolean is_moving = true;				while(is_moving){			is_moving = false;						for(int index = 0; index < robots.length; index++)				if(! robots[index].stillSearching()){					robots[index].move();					is_moving = true;				}			draw(page);		}	}	public void draw(Graphics page){			my_room.draw(page);		for(int index = 0; index < robots.length; index++){			page.setColor(colors[index]);			robots[index].draw(page);		}					an_obstacle.draw(page);		your_goal.draw(page);		}}